+    expect({
+      legacyOptions: legacyProbe.options,
+      modernOptions: modernProbe.options,
+      legacyResult: legacyResult.result,
+      emptyErrorsResult: emptyErrorsResult.result,
+      modernResult: modernResult.result,
+    }).toEqual({
+      legacyOptions: [{allErrors: true, format: false, jsonPointers: true}],
+      modernOptions: [{allErrors: true, strict: false, validateFormats: false}],
+      legacyResult:
