+    });
+  });
 });
+
+function buildLegacyCompilerProbe(): {compiler: ValidatorCompiler; options: Array<Record<string, unknown>>} {
+  const options: Array<Record<string, unknown>> = [];
+  let invocationCount = 0;
+  class LegacyCompilerStub implements ValidatorCompiler {
+    constructor(receivedOptions: Record<string, unknown>) {
+      options.push(receivedOptions);
+    }
+
+    compile(): SchemaValidator {
+      const validate: SchemaValidator = () => {
+        invocationCount += 1;
+        if (invocationCount > 1) {
+          validate.errors = null;
+          return false;
+        }
+        validate.errors = [
+          {keyword: 'type', dataPath: '/ssn', params: {type: 'string'}},
+          {keyword: 'type', dataPath: '.legacyZip', params: {type: 'string'}},
+          {keyword: 'minProperties', params: {limit: 1}},
+        ];
+        return false;
+      };
+      return validate;
+    }
+  }
+  return {compiler: createValidatorCompiler({default: LegacyCompilerStub}), options};
+}
+
+function buildModernCompilerProbe(): {compiler: ValidatorCompiler; options: Array<Record<string, unknown>>} {
+  const options: Array<Record<string, unknown>> = [];
+  class ModernCompilerStub implements ValidatorCompiler {
+    constructor(receivedOptions: Record<string, unknown>) {
+      options.push(receivedOptions);
+    }
+
+    _addVocabularies(): void {}
+
+    compile(): SchemaValidator {
+      const validate: SchemaValidator = () => {
+        validate.errors = [{keyword: 'type', instancePath: '/city', params: {type: 'string'}}];
+        return false;
+      };
+      return validate;
+    }
+  }
+  return {compiler: createValidatorCompiler(ModernCompilerStub), options};
+}
